function UIActionPointMapBossNode:Refresh(activityPrefabId, activityContentId, id, index)
    self.activityPrefabId = activityPrefabId
    self.activityContentId = activityContentId

    self.questVo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not self.questVo then
        return
    end
    self.btnIndex = checkNumber(index)
    self:FillSelf()
end

function UIActionPointMapBossNode:FillSelf()
    CfUtils.FillText(self.TxtNumber, self.questVo.label)

    local vo = self.questVo
    if isNull(vo) then
        return
    end
    local isUnlocked = AnnihilationUtils.IsUnlockBossQuest(self.activityPrefabId, self.activityContentId, vo.monsterType, vo.id)
    CfUtils.SetUISwitchText(self.TxtNumber, isUnlocked and 1 or 3)

    local animRoot, animName
    if self.activityPrefabId == 0 then
        animRoot = self.CellRoot.gameObject
        animName = "ActionPointMapDialog_Boss_Cell_DropDown"
    else
        animRoot = self.controller.gameObject
        animName = "ActivityDreamAdventureslStoryMapBossMain_Cell_Show"
        CfUtils.PlayAnimation(animRoot, "UI_Common_List_Cell_Hide")
    end
    self._co = CfUtils.PlayDelayShowAnimate(animRoot, self.btnIndex, 0.05, 0, animName)
end

function UIActionPointMapBossNode:FillSelect(isSelect)
    if self._selectCo ~= nil then
        cs_coroutine.stop(self._selectCo)
        self._selectCo = nil
    end
    local vo = self.questVo
    if isNull(vo) then
        return
    end

    local animRoot
    if self.activityPrefabId == 0 then
        animRoot = self.controller.gameObject
    else
        animRoot = self.CellRoot.gameObject
    end
    local comp = AnnihilationUtils.GetComponent(self.activityPrefabId)
    local animNamePrefix = comp:GetSelectQuestDialogAnimationPrefix()

    local isUnlocked = AnnihilationUtils.IsUnlockBossQuest(self.activityPrefabId, self.activityContentId, vo.monsterType, vo.id)
    self._selectCo = cs_coroutine.start(function()
        if isSelect then
            if isUnlocked then
                CfUtils.PlayAnimation(animRoot, string.format("%s_Cell_Selecting", animNamePrefix))
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
                CfUtils.PlayAnimation(animRoot, string.format("%s_Cell_Selected", animNamePrefix))
            else
                CfUtils.PlayAnimation(animRoot, string.format("%s_Cell_Locked_Selecting", animNamePrefix))
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
                CfUtils.PlayAnimation(animRoot, string.format("%s_Cell_Locked_Selected", animNamePrefix))
            end
        else
            if isUnlocked then
                CfUtils.PlayAnimation(animRoot, string.format("%s_Cell_Normal", animNamePrefix))
            else
                CfUtils.PlayAnimation(animRoot, string.format("%s_Cell_Locked", animNamePrefix))
            end
        end
    end)

    if isSelect then
        CfUtils.SetUISwitchText(self.TxtNumber, 2)
    else
        CfUtils.SetUISwitchText(self.TxtNumber, isUnlocked and 1 or 3)
    end
end 

function UIActionPointMapBossNode:SetClickCallback(callback)
    SetButtonAction(self.controller.gameObject, function()
        callback(self)
    end)
end

function UIActionPointMapBossNode:OnDestroy()
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    if self._selectCo then 
        cs_coroutine.stop(self._selectCo)
        self._selectCo = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionPointMapBossNode